Debounce delay API call until user stop typing. Assume React. Vanilla version below.

**Hook:**

```ts
import { useEffect, useState } from "react";

export function useDebounce<T>(value: T, delay = 300): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);

  return debounced;
}
```

**Search component:**

```tsx
import { useEffect, useState } from "react";
import { useDebounce } from "./useDebounce";

export function Search() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<any[]>([]);
  const debouncedQuery = useDebounce(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }

    const controller = new AbortController();

    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((r) => r.json())
      .then(setResults)
      .catch((err) => {
        if (err.name !== "AbortError") console.error(err);
      });

    return () => controller.abort(); // cancel stale request
  }, [debouncedQuery]);

  return (
    <>
      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />
      <ul>
        {results.map((r) => (
          <li key={r.id}>{r.name}</li>
        ))}
      </ul>
    </>
  );
}
```

**Vanilla JS:**

```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const input = document.querySelector("#search");
let controller;

const search = async (q) => {
  controller?.abort();
  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`, {
      signal: controller.signal,
    });
    render(await res.json());
  } catch (e) {
    if (e.name !== "AbortError") console.error(e);
  }
};

input.addEventListener("input", debounce((e) => search(e.target.value), 300));
```

Notes:
- Input stay controlled on `query` → typing feel instant. Only API use `debouncedQuery`.
- `AbortController` kill in-flight request → no out-of-order response overwrite newer results.
- 250–400ms typical delay. Lower = more calls, higher = feel laggy.
- Empty query skip fetch.
